INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20QPN2X', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which of the following values of $x$ satisfies the inequality $5 - 2x > 11$?', NULL, $lyceon_json$[{"key":"A","text":"$-5$"},{"key":"B","text":"$-3$"},{"key":"C","text":"$0$"},{"key":"D","text":"$4$"}]$lyceon_json$::jsonb, 'A', NULL, E'Solving $5 - 2x > 11$: subtract $5$ from both sides to get $-2x > 6$, then divide by $-2$ and reverse the inequality to get $x < -3$. Of the choices, only $-5$ is less than $-3$. The value $-3$ does not satisfy the inequality because it is strict ($<$, not $\\leq$). The value $0$ results from failing to reverse the inequality direction when dividing by a negative number, yielding $x > -3$. The value $4$ arises from a sign error when isolating $x$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21KJE39', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'grid_in', E'The quadratic function $f(x) = ax^2 + bx + c$ has a vertex at $(3, -17)$ and passes through the point $(5, -9)$. What is the value of $a$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '2', ARRAY['2'], E'Using vertex form, the function can be written as $f(x) = a(x - 3)^2 - 17$. Substituting the point $(5, -9)$ gives $-9 = a(5 - 3)^2 - 17$, so $-9 = 4a - 17$. Adding $17$ to both sides yields $8 = 4a$, and dividing by $4$ gives $a = 2$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22IYWXZ', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'grid_in', E'A linear function $h$ satisfies $h(3) = 19$ and $h(11) = 51$. What is $h(0)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'The slope of $h$ is $\\frac{51 - 19}{11 - 3} = \\frac{32}{8} = 4$. Using the point $(3, 19)$, the function is $h(x) = 4(x - 3) + 19 = 4x - 12 + 19 = 4x + 7$. Therefore $h(0) = 4(0) + 7 = 7$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22K74UW', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $\\frac{2x^2 + 7x - 15}{2x^2 - 5x + 3}$ for all values of $x$ where the expression is defined?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{x + 5}{x - 1}$"},{"key":"B","text":"$\\frac{x - 5}{x - 1}$"},{"key":"C","text":"$\\frac{x + 5}{x + 3}$"},{"key":"D","text":"$\\frac{2x + 5}{2x - 1}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factor the numerator $2x^2 + 7x - 15$ as $(2x - 3)(x + 5)$ and the denominator $2x^2 - 5x + 3$ as $(2x - 3)(x - 1)$. Canceling the common factor $(2x - 3)$ gives $\\frac{x + 5}{x - 1}$. The expression $\\frac{x - 5}{x - 1}$ results from a sign error when factoring the numerator. The expression $\\frac{x + 5}{x + 3}$ comes from an arithmetic slip in factoring the denominator. The expression $\\frac{2x + 5}{2x - 1}$ arises from incompletely factoring each trinomial and failing to identify the common binomial factor.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22VB2PL', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What is the value of $x$ in the equation $6x - 15 = 33$?', NULL, $lyceon_json$[{"key":"A","text":"$8$"},{"key":"B","text":"$-8$"},{"key":"C","text":"$3$"},{"key":"D","text":"$48$"}]$lyceon_json$::jsonb, 'A', NULL, E'Adding $15$ to both sides of $6x - 15 = 33$ gives $6x = 48$, and dividing both sides by $6$ gives $x = 8$. The value $-8$ results from a sign error when dividing. The value $3$ comes from subtracting $15$ from $33$ instead of adding, yielding $\\frac{18}{6}$. The value $48$ is the intermediate result $6x = 48$ before dividing by $6$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM243AO37', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'If $x > 0$ and $x^2 + 5x = 84$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$12$"},{"key":"C","text":"$9$"},{"key":"D","text":"$84$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rearranging gives $x^2 + 5x - 84 = 0$. To factor, find two numbers that multiply to $-84$ and add to $5$: those are $12$ and $-7$, so the equation factors as $(x + 12)(x - 7) = 0$, giving $x = -12$ or $x = 7$. Since $x > 0$, the answer is $x = 7$. The value $12$ results from a sign error, using the magnitude of the negative root. The value $9$ comes from an arithmetic slip in the factoring step. The value $84$ reflects a misunderstanding of the equation structure, confusing the constant term for the solution.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24BNKG2', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which expression is equivalent to $\\frac{x^7 \\cdot x^3}{x^4}$?', NULL, $lyceon_json$[{"key":"A","text":"$x^6$"},{"key":"B","text":"$x^{14}$"},{"key":"C","text":"$x^{\\frac{21}{4}}$"},{"key":"D","text":"$x^4$"}]$lyceon_json$::jsonb, 'A', NULL, E'When multiplying powers with the same base, add the exponents: $x^7 \\cdot x^3 = x^{10}$. When dividing powers with the same base, subtract the exponents: $\\frac{x^{10}}{x^4} = x^{10 - 4} = x^6$. The choice $x^{14}$ results from adding all three exponents ($7 + 3 + 4 = 14$) instead of adding the numerator exponents and then subtracting the denominator exponent. The choice $x^{\\frac{21}{4}}$ results from multiplying the numerator exponents and dividing by the denominator exponent. The choice $x^4$ comes from subtracting $7 - 3 = 4$ instead of adding the exponents in the numerator.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM258L57F', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'The system of equations $ax + 8y = 14$ and $5x + 2y = 7$ has no solution. What is the value of $a$?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$8$"},{"key":"C","text":"$20$"},{"key":"D","text":"$-20$"}]$lyceon_json$::jsonb, 'C', NULL, E'A system of two linear equations has no solution when the lines are parallel — that is, the ratios of the coefficients of $x$ and $y$ are equal but the ratio of the constants is different. Setting $\\frac{a}{5} = \\frac{8}{2}$ gives $\\frac{a}{5} = 4$, so $a = 20$. Checking the constants: $\\frac{14}{7} = 2 \\neq 4$, confirming the system is inconsistent. The value $4$ results from finding the common ratio but not multiplying by $5$ to solve for $a$. The value $8$ comes from selecting a coefficient that already appears in the system rather than computing the required value. The value $-20$ introduces an incorrect sign.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM268OP8K', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $f(x) = (x - 7)^2 + 11$ is defined. What is the minimum value of $f(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$-7$"},{"key":"B","text":"$7$"},{"key":"C","text":"$11$"},{"key":"D","text":"$-11$"}]$lyceon_json$::jsonb, 'C', NULL, E'The function is in vertex form $f(x) = (x - 7)^2 + 11$, where the vertex is at $(7, 11)$. Since the coefficient of the squared term is positive, the parabola opens upward and the vertex represents the minimum. The minimum value of $f(x)$ is $11$. Choosing $7$ confuses the $x$-coordinate of the vertex with the minimum output value. Choosing $-7$ or $-11$ results from incorrectly negating the vertex coordinates.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27GIX61', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'grid_in', E'A plumber charges a flat fee of $\\$47$ plus $\\$31$ per hour of labor. If the total bill was $\\$233$, how many hours of labor were performed?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6', ARRAY['6'], E'The total bill is modeled by $47 + 31h = 233$, where $h$ is the number of hours. Subtracting $47$ from both sides gives $31h = 186$. Dividing both sides by $31$ gives $h = 6$. Therefore, $6$ hours of labor were performed.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2880WFU', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the slope of the line represented by $3x + 5y = 20$?', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{3}{5}$"},{"key":"B","text":"$\\frac{3}{5}$"},{"key":"C","text":"$4$"},{"key":"D","text":"$\\frac{5}{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rearranging $3x + 5y = 20$ into slope-intercept form: $5y = -3x + 20$, so $y = -\\frac{3}{5}x + 4$. The slope is $-\\frac{3}{5}$. The value $\\frac{3}{5}$ results from a sign error when moving the $3x$ term to the other side. The value $4$ is the $y$-intercept, not the slope. The value $\\frac{5}{3}$ is the reciprocal of the correct slope magnitude, resulting from dividing the coefficients in the wrong order.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM294VNG8', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A health magazine reports that adults who drink green tea daily have a $30\\%$ lower rate of heart disease than adults who do not, based on a survey of 5,000 adults. Which of the following is the most appropriate conclusion from this study?', NULL, $lyceon_json$[{"key":"A","text":"Drinking green tea daily causes a $30\\%$ reduction in heart disease risk."},{"key":"B","text":"There is an association between daily green tea consumption and a lower rate of heart disease, but the survey alone cannot establish that green tea causes the reduction."},{"key":"C","text":"The study proves that green tea has no meaningful effect on heart disease."},{"key":"D","text":"If the study had included more participants, it would have been able to prove that green tea prevents heart disease."}]$lyceon_json$::jsonb, 'B', NULL, E'Because this was a survey, which is an observational study rather than a randomized controlled experiment, it can identify an association but cannot establish causation. Confounding variables such as diet, exercise habits, or socioeconomic factors may explain the observed difference. The claim that green tea causes the reduction incorrectly treats an observational finding as causal evidence. The claim that the study proves no effect directly contradicts the reported $30\\%$ lower rate. The claim that a larger sample size would prove causation is incorrect because increasing sample size does not convert an observational study into an experiment capable of establishing cause and effect.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29FIS61', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'The sum of three consecutive odd integers is $141$. What is the largest of the three integers?', NULL, $lyceon_json$[{"key":"A","text":"$45$"},{"key":"B","text":"$49$"},{"key":"C","text":"$47$"},{"key":"D","text":"$51$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let the three consecutive odd integers be $x$, $x + 2$, and $x + 4$. Their sum is $3x + 6 = 141$, so $3x = 135$ and $x = 45$. The three integers are $45$, $47$, and $49$, and the largest is $49$. The value $45$ is the smallest integer, not the largest. The value $47$ is the middle integer, chosen if the question is misread as asking for the middle value. The value $51$ results from an arithmetic slip, such as computing $x = 45$ and then adding $6$ instead of $4$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AJOQMM', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'How many distinct real solutions does the equation $3x^2 - 10x + 11 = 0$ have?', NULL, $lyceon_json$[{"key":"A","text":"Zero"},{"key":"B","text":"Exactly one"},{"key":"C","text":"Exactly two"},{"key":"D","text":"Exactly three"}]$lyceon_json$::jsonb, 'A', NULL, E'The number of real solutions is determined by the discriminant $b^2 - 4ac$. For $3x^2 - 10x + 11 = 0$, the discriminant is $(-10)^2 - 4(3)(11) = 100 - 132 = -32$. Since the discriminant is negative, the equation has zero real solutions. The choice stating exactly one solution would require the discriminant to equal zero. The choice stating exactly two solutions would require a positive discriminant. The choice stating three solutions is impossible for a quadratic equation, which has at most two solutions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AUVKRT', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle in the $xy$-plane has the equation $(x + 3)^2 + (y - 11)^2 = 49$. What are the center and the radius of the circle?', NULL, $lyceon_json$[{"key":"A","text":"Center $(-3, 11)$, radius $7$"},{"key":"B","text":"Center $(3, -11)$, radius $7$"},{"key":"C","text":"Center $(-3, 11)$, radius $49$"},{"key":"D","text":"Center $(-3, -11)$, radius $7$"}]$lyceon_json$::jsonb, 'A', NULL, E'The standard form of a circle is $(x - h)^2 + (y - k)^2 = r^2$, where $(h, k)$ is the center and $r$ is the radius. Rewriting $(x + 3)^2$ as $(x - (-3))^2$ shows $h = -3$. The term $(y - 11)^2$ gives $k = 11$. Since $r^2 = 49$, the radius is $r = 7$. The center $(3, -11)$ with radius $7$ results from taking the opposite signs of the constants without applying the sign convention of the standard form. The center $(-3, 11)$ with radius $49$ correctly identifies the center but confuses $r^2 = 49$ with $r = 49$, giving the squared radius instead of the radius. The center $(-3, -11)$ with radius $7$ has the correct $x$-coordinate and radius but reverses the sign of the $y$-coordinate.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AW43XS', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which expression is equivalent to $\\frac{2x^2 + 11x - 21}{x^2 - 9} \\cdot \\frac{x^2 + 6x + 9}{4x^2 - 9}$ for all values of $x$ where the expression is defined?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{(x + 7)(x + 3)}{(x - 3)(2x + 3)}$"},{"key":"B","text":"$\\frac{x + 7}{(x - 3)(2x + 3)}$"},{"key":"C","text":"$\\frac{(x + 7)(x + 3)}{(x - 3)(2x - 3)}$"},{"key":"D","text":"$\\frac{(x + 7)}{(2x + 3)}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factor each polynomial: $2x^2 + 11x - 21 = (2x - 3)(x + 7)$, $x^2 - 9 = (x - 3)(x + 3)$, $x^2 + 6x + 9 = (x + 3)^2$, and $4x^2 - 9 = (2x - 3)(2x + 3)$. The product becomes $\\frac{(2x - 3)(x + 7)}{(x - 3)(x + 3)} \\cdot \\frac{(x + 3)^2}{(2x - 3)(2x + 3)}$. Cancel the common factors $(2x - 3)$ and one $(x + 3)$ to obtain $\\frac{(x + 7)(x + 3)}{(x - 3)(2x + 3)}$. The choice $\\frac{x + 7}{(x - 3)(2x + 3)}$ incorrectly cancels both factors of $(x + 3)$ instead of only one. The choice with $(2x - 3)$ in the denominator uses a sign error, confusing $2x + 3$ with $2x - 3$. The choice $\\frac{x + 7}{2x + 3}$ cancels the $(x - 3)$ factor as if it appeared in the numerator.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BF404G', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'What is the $x$-intercept of the line that passes through the point $(3, 17)$ and has a slope of $-2$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '23/2', ARRAY['23/2', '11.5'], E'Using point-slope form with the point $(3, 17)$ and slope $-2$: $y - 17 = -2(x - 3)$, which simplifies to $y = -2x + 23$. The $x$-intercept occurs when $y = 0$: $0 = -2x + 23$, so $2x = 23$ and $x = \\frac{23}{2}$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BMASAO', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A delivery service charges a flat fee of \\$19 plus \\$4 per mile driven. A customer has a budget of at most \\$75 for a delivery. Which inequality represents all possible distances $m$, in miles, the customer can afford?', NULL, $lyceon_json$[{"key":"A","text":"$19 + 4m \\leq 75$"},{"key":"B","text":"$19 + 4m \\geq 75$"},{"key":"C","text":"$4 + 19m \\leq 75$"},{"key":"D","text":"$19 + 4m < 75$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total cost is the flat fee of \\$19 plus \\$4 times the number of miles: $19 + 4m$. Since the customer can spend at most \\$75, the total cost must be less than or equal to \\$75, giving $19 + 4m \\leq 75$. The inequality $19 + 4m \\geq 75$ reverses the direction, incorrectly requiring the cost to be at least \\$75. The expression $4 + 19m \\leq 75$ swaps the flat fee and per-mile rate. The strict inequality $19 + 4m < 75$ misreads "at most" as strictly less than, when the customer can spend exactly \\$75.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DP2JNJ', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'grid_in', E'$3x + 2y = 19$ and $x - 2y = -7$. What is the value of $y$ in the solution to the system of equations?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Adding the two equations eliminates $y$: $(3x + 2y) + (x - 2y) = 19 + (-7)$, which simplifies to $4x = 12$, so $x = 3$. Substituting $x = 3$ into $x - 2y = -7$ gives $3 - 2y = -7$, so $-2y = -10$ and $y = 5$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DUG1HT', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A rectangular garden measures $13$ meters long and $9$ meters wide. A uniform path that is $2$ meters wide borders the inside of the garden along all four sides. What is the area, in square meters, of the path?', NULL, $lyceon_json$[{"key":"A","text":"$40$"},{"key":"B","text":"$45$"},{"key":"C","text":"$72$"},{"key":"D","text":"$88$"}]$lyceon_json$::jsonb, 'C', NULL, E'The total area of the garden is $13 \\times 9 = 117$ square meters. The path is $2$ meters wide on each side, so the inner rectangle has dimensions $(13 - 2 \\times 2)$ by $(9 - 2 \\times 2) = 9$ by $5$, giving an inner area of $45$ square meters. The area of the path is $117 - 45 = 72$ square meters. The value $40$ results from subtracting only $2$ (instead of $4$) from each dimension, yielding inner dimensions of $11 \\times 7 = 77$ and a path area of $117 - 77 = 40$. The value $45$ is the inner area, not the path area. The value $88$ comes from incorrectly computing the path area as perimeter times width: $2(13 + 9) \\times 2 = 88$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EQSBZ7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A researcher surveys a random sample of 1,600 city residents and finds that $38\\%$ support a proposed policy, with a margin of error of 2.4 percentage points at the $95\\%$ confidence level. A separate random sample of 400 residents from the same city finds $41\\%$ support the same policy. Which of the following statements is best supported by this information?', NULL, $lyceon_json$[{"key":"A","text":"The two surveys give contradictory results, so at least one must have used a biased sampling method."},{"key":"B","text":"The larger survey's result of $38\\%$ is the true proportion of city residents who support the policy."},{"key":"C","text":"Because the confidence intervals from the two surveys overlap, the results are consistent with the same population proportion."},{"key":"D","text":"Since both surveys found support below $50\\%$, the policy will certainly be defeated in a public vote."}]$lyceon_json$::jsonb, 'C', NULL, E'The first survey''s $95\\%$ confidence interval is $38\\% \\pm 2.4$, or $35.6\\%$ to $40.4\\%$. For the second survey with one-quarter the sample size, the margin of error is approximately twice as large, about 4.8 percentage points, giving an interval of roughly $36.2\\%$ to $45.8\\%$. These intervals overlap substantially, so the two results are consistent with the same underlying population proportion. The claim that the surveys are contradictory ignores that different random samples naturally yield different point estimates within their margins of error. Equating the sample statistic of $38\\%$ with the true population proportion confuses a point estimate with the parameter it estimates. Concluding that the policy will certainly fail extrapolates beyond what confidence intervals can determine, since confidence intervals describe estimation precision, not election outcomes.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GJW4CL', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $g(x) = -2(x + 4)^2 + 19$ is defined. Which of the following statements about $g$ is true?', NULL, $lyceon_json$[{"key":"A","text":"$g$ has a minimum value of $19$"},{"key":"B","text":"$g$ has a maximum value of $-4$"},{"key":"C","text":"$g$ has a minimum value of $-4$"},{"key":"D","text":"$g$ has a maximum value of $19$"}]$lyceon_json$::jsonb, 'D', NULL, E'The function $g(x) = -2(x + 4)^2 + 19$ is in vertex form with a negative leading coefficient ($-2$), so the parabola opens downward and the vertex at $(-4, 19)$ is a maximum. The maximum value of $g$ is $19$. Stating that $g$ has a minimum of $19$ reverses the direction of the parabola. Choosing $-4$ as the extreme value confuses the $x$-coordinate of the vertex with the function''s output value.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GRL848', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'If $x > 0$, $x^2 + y = 19$, and $x + y = 7$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'From the equation $x + y = 7$, solve for $y$ to get $y = 7 - x$. Substitute into $x^2 + y = 19$: $x^2 + (7 - x) = 19$, which simplifies to $x^2 - x + 7 = 19$, or $x^2 - x - 12 = 0$. Factor as $(x - 4)(x + 3) = 0$, giving $x = 4$ or $x = -3$. Since $x > 0$, the value is $x = 4$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H2VT9Z', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a diameter of $18$ centimeters. What is the circumference of the circle, in centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$9\\pi$"},{"key":"B","text":"$18\\pi$"},{"key":"C","text":"$36\\pi$"},{"key":"D","text":"$81\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The circumference of a circle is $C = \\pi d$, where $d$ is the diameter. Substituting $d = 18$ gives $C = 18\\pi$ centimeters. The value $9\\pi$ results from using the radius ($9$) in the formula $C = \\pi r$ instead of $C = 2\\pi r$ or $C = \\pi d$. The value $36\\pi$ comes from mistakenly using $C = 2\\pi d$ instead of $C = \\pi d$. The value $81\\pi$ results from applying the area formula $\\pi r^2 = \\pi(9)^2 = 81\\pi$ instead of the circumference formula.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HGDYL5', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $f(x) = -3x + 22$ models the remaining balance, in dollars, on a gift card after $x$ purchases. What does the value $-3$ represent in this context?', NULL, $lyceon_json$[{"key":"A","text":"The balance decreases by $\\$3$ per purchase."},{"key":"B","text":"The balance increases by $\\$3$ per purchase."},{"key":"C","text":"The initial balance on the gift card is $\\$3$."},{"key":"D","text":"A total of $3$ purchases have been made."}]$lyceon_json$::jsonb, 'A', NULL, E'In $f(x) = -3x + 22$, the coefficient $-3$ is the slope, which represents the rate of change of the balance per purchase. Since it is negative, the balance decreases by $\\$3$ with each purchase. The claim that the balance increases by $\\$3$ ignores the negative sign. The claim about the initial balance confuses the slope with the $y$-intercept, which is $22$. The claim about $3$ total purchases misinterprets the coefficient as a quantity rather than a rate.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HPUR1J', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $p$ passes through the points $(1, -5)$ and $(4, 7)$. Line $q$ is perpendicular to line $p$ and passes through the point $(8, 3)$. What is the $y$-intercept of line $q$?', NULL, $lyceon_json$[{"key":"A","text":"$-5$"},{"key":"B","text":"$3$"},{"key":"C","text":"$5$"},{"key":"D","text":"$-\\frac{1}{4}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The slope of line $p$ is $\\frac{7 - (-5)}{4 - 1} = \\frac{12}{3} = 4$. A line perpendicular to $p$ has slope $-\\frac{1}{4}$. Using point-slope form with $(8, 3)$: $y - 3 = -\\frac{1}{4}(x - 8)$, which gives $y = -\\frac{1}{4}x + 2 + 3 = -\\frac{1}{4}x + 5$. The $y$-intercept is $5$. The value $-5$ results from a sign error in combining the constant terms. The value $3$ is the $y$-coordinate of the given point on line $q$, not the $y$-intercept. The value $-\\frac{1}{4}$ is the slope of line $q$, not its $y$-intercept.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HTZCXB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'grid_in', E'A printing machine produces 119 pages every 7 minutes. At this constant rate, how many pages does the machine produce in 51 minutes?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '867', ARRAY['867'], E'The machine''s rate is $\\frac{119}{7} = 17$ pages per minute. In 51 minutes, the machine produces $17 \\times 51 = 867$ pages.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I0FVCU', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'grid_in', E'In a group of 250 athletes, 150 play soccer, 100 play basketball, and 50 play both sports. If one athlete is selected at random from those who play soccer, what is the probability that this athlete also plays basketball?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '1/3', ARRAY['1/3', '0.333', '.333'], E'Among the 150 athletes who play soccer, 50 also play basketball. The conditional probability is $\\frac{50}{150} = \\frac{1}{3}$. A common error is dividing 50 by the total of 250, which gives $\\frac{1}{5}$; however, that is the probability of selecting a dual-sport athlete from the entire group, not from the soccer players specifically. Another error is dividing 50 by 100, which conditions on basketball players instead of soccer players.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JGZ0VS', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'A university surveyed 640 students about study habits. Of these students, $35\\%$ reported studying more than 20 hours per week. Among those who study more than 20 hours per week, $25\\%$ also hold a part-time job. How many surveyed students both study more than 20 hours per week and hold a part-time job?', NULL, $lyceon_json$[{"key":"A","text":"56"},{"key":"B","text":"160"},{"key":"C","text":"224"},{"key":"D","text":"384"}]$lyceon_json$::jsonb, 'A', NULL, E'First, $35\\%$ of 640 students study more than 20 hours per week: $0.35 \\times 640 = 224$ students. Then $25\\%$ of those 224 students also hold a part-time job: $0.25 \\times 224 = 56$ students. The value 160 results from incorrectly applying $25\\%$ to the entire group of 640 instead of the subset of 224. The value 224 comes from completing only the first percentage calculation and stopping. The value 384 results from adding the two percentages ($35\\% + 25\\% = 60\\%$) and applying that combined rate to 640.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KAEI2X', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'grid_in', E'If $(x + 2)$ is a factor of $3x^3 + kx^2 - 17x + 6$, what is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-4', ARRAY['-4'], E'If $(x + 2)$ is a factor of the polynomial, then the polynomial equals zero when $x = -2$ by the Factor Theorem. Substitute $x = -2$: $3(-2)^3 + k(-2)^2 - 17(-2) + 6 = 0$. This simplifies to $3(-8) + k(4) + 34 + 6 = 0$, which gives $-24 + 4k + 34 + 6 = 0$. Combining the constants: $4k + 16 = 0$, so $4k = -16$ and $k = -4$.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KQML8J', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What is the solution to $\\sqrt{x + 11} = 7$?', NULL, $lyceon_json$[{"key":"A","text":"$x = 60$"},{"key":"B","text":"$x = 38$"},{"key":"C","text":"$x = -38$"},{"key":"D","text":"$x = 18$"}]$lyceon_json$::jsonb, 'B', NULL, E'Square both sides of $\\sqrt{x + 11} = 7$ to get $x + 11 = 49$. Subtract $11$ from both sides to find $x = 38$. The choice $x = 60$ results from adding $11$ to $49$ instead of subtracting. The choice $x = -38$ applies the correct operations but introduces a sign error. The choice $x = 18$ comes from an arithmetic mistake, such as computing $7^2 = 29$ or subtracting incorrectly.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KZJGZM', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'The function $g$ is defined by $g(x) = \\frac{5}{2}x - 9$. If $g(a) = 16$, what is the value of $a$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{14}{5}$"},{"key":"B","text":"$-10$"},{"key":"C","text":"$25$"},{"key":"D","text":"$10$"}]$lyceon_json$::jsonb, 'D', NULL, E'Setting $g(a) = 16$ gives $\\frac{5}{2}a - 9 = 16$. Adding $9$ to both sides yields $\\frac{5}{2}a = 25$. Multiplying both sides by $\\frac{2}{5}$ gives $a = 10$. The value $\\frac{14}{5}$ results from subtracting $9$ from $16$ to get $7$ and then dividing by $\\frac{5}{2}$, which means $9$ was subtracted instead of added. The value $-10$ is a sign error on the final answer. The value $25$ is the intermediate result $\\frac{5}{2}a = 25$ before the final division.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L53NCJ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'A population of bacteria is modeled by $P(t) = 850 \\cdot (1.37)^t$, where $t$ is the number of hours after the initial measurement. Which of the following is the best interpretation of $1.37$ in this context?', NULL, $lyceon_json$[{"key":"A","text":"The population increases by $137$ bacteria each hour"},{"key":"B","text":"The population is $1.37$ times as large each hour as it was the previous hour"},{"key":"C","text":"The initial population of bacteria is $1.37$"},{"key":"D","text":"The population reaches $1.37$ times its initial size after the first hour only and then grows at a constant rate"}]$lyceon_json$::jsonb, 'B', NULL, E'In the exponential model $P(t) = 850 \\cdot (1.37)^t$, the base $1.37$ is the growth factor applied each hour. This means the population is $1.37$ times as large each hour as it was the previous hour, corresponding to a $37\\%$ hourly increase. Interpreting $1.37$ as an additive increase of $137$ bacteria per hour confuses exponential growth with linear growth. Identifying $1.37$ as the initial population mistakes the base for the coefficient $850$. Claiming the factor applies only to the first hour and then becomes constant mischaracterizes the repeated multiplicative nature of exponential growth.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M4C9YI', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $9x^2 - 49$?', NULL, $lyceon_json$[{"key":"A","text":"$(9x - 49)(9x + 49)$"},{"key":"B","text":"$(3x - 7)(3x + 7)$"},{"key":"C","text":"$(3x - 7)^2$"},{"key":"D","text":"$(9x - 7)(x + 7)$"}]$lyceon_json$::jsonb, 'B', NULL, E'The expression $9x^2 - 49$ is a difference of two squares, since $9x^2 = (3x)^2$ and $49 = 7^2$. Applying the identity $a^2 - b^2 = (a - b)(a + b)$ with $a = 3x$ and $b = 7$ gives $(3x - 7)(3x + 7)$. The choice $(9x - 49)(9x + 49)$ incorrectly treats $9x^2$ and $49$ as the bases rather than taking their square roots. The choice $(3x - 7)^2$ expands to $9x^2 - 42x + 49$, which includes a middle term not present in the original. The choice $(9x - 7)(x + 7)$ results from incorrectly splitting the coefficients.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MMJBC5', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'A store purchases an item at wholesale cost and marks it up by $60\\%$ to set the retail price. During a clearance event, the retail price is reduced by $25\\%$. An employee then applies an additional $20\\%$ employee discount to the clearance price. The price the employee pays is what percent of the original wholesale cost?', NULL, $lyceon_json$[{"key":"A","text":"$60\\%$"},{"key":"B","text":"$96\\%$"},{"key":"C","text":"$115\\%$"},{"key":"D","text":"$120\\%$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let the wholesale cost be $W$. The retail price is $1.60W$. After the $25\\%$ clearance reduction, the price becomes $1.60W \\times 0.75 = 1.20W$. After the $20\\%$ employee discount, the final price is $1.20W \\times 0.80 = 0.96W$, which is $96\\%$ of the wholesale cost. The value $60\\%$ results from ignoring the markup entirely and computing only $0.75 \\times 0.80 = 0.60$. The value $115\\%$ comes from incorrectly subtracting percentages from the marked-up price: $160\\% - 25\\% - 20\\% = 115\\%$. The value $120\\%$ results from applying only the clearance discount: $1.60 \\times 0.75 = 1.20$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N5ZPGN', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'grid_in', E'The function $h(x) = x^2 - 14x + 53$ is defined. What is the minimum value of $h(x)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'Completing the square: $h(x) = x^2 - 14x + 53 = (x - 7)^2 - 49 + 53 = (x - 7)^2 + 4$. Since $(x - 7)^2 \\geq 0$ for all real $x$, the minimum value of $h(x)$ occurs when $(x - 7)^2 = 0$, which gives $h(7) = 4$. The minimum value is $4$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N7EDCM', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'If $\\frac{5(x + 3)}{2} = 35$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$14$"},{"key":"B","text":"$4$"},{"key":"C","text":"$11$"},{"key":"D","text":"$-11$"}]$lyceon_json$::jsonb, 'C', NULL, E'Multiplying both sides by $2$ gives $5(x + 3) = 70$. Dividing both sides by $5$ gives $x + 3 = 14$. Subtracting $3$ yields $x = 11$. The value $14$ is the intermediate result before subtracting $3$. The value $4$ comes from dividing $35$ by $5$ to get $7$ and then subtracting $3$, neglecting the factor of $2$ in the denominator. The value $-11$ results from a sign error in the final step.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2O0QYNB', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'grid_in', E'The function $f(x) = 3 \\cdot 2^x$ is defined. What is the value of $f(5)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '96', ARRAY['96'], E'Substituting $x = 5$ into the function gives $f(5) = 3 \\cdot 2^5 = 3 \\cdot 32 = 96$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2O1W10G', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A theater sells adult tickets for \\$13 each and child tickets for \\$7 each. On one evening, 83 tickets were sold for a total of \\$839. How many adult tickets were sold?', NULL, $lyceon_json$[{"key":"A","text":"$34$"},{"key":"B","text":"$40$"},{"key":"C","text":"$43$"},{"key":"D","text":"$53$"}]$lyceon_json$::jsonb, 'C', NULL, E'Let $a$ be the number of adult tickets and $c$ the number of child tickets. The system is $a + c = 83$ and $13a + 7c = 839$. Substituting $c = 83 - a$ into the revenue equation: $13a + 7(83 - a) = 839$, so $13a + 581 - 7a = 839$, giving $6a = 258$ and $a = 43$. The value $40$ is the number of child tickets, which answers the wrong question. The value $34$ results from an error in setting up the revenue equation. The value $53$ comes from a computational error during the elimination step.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OE48M8', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'grid_in', E'A line passes through the points $(-1, 17)$ and $(3, -7)$. If the line also passes through the point $(k, -19)$, what is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'The slope of the line is $\\frac{-7 - 17}{3 - (-1)} = \\frac{-24}{4} = -6$. Using point-slope form with $(-1, 17)$: $y - 17 = -6(x + 1)$, which gives $y = -6x + 11$. Substituting $y = -19$: $-19 = -6k + 11$, so $-6k = -30$ and $k = 5$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ONA1OW', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'What is the solution to $\\frac{5}{x - 2} = \\frac{3}{x + 1}$?', NULL, $lyceon_json$[{"key":"A","text":"$x = \\frac{11}{2}$"},{"key":"B","text":"$x = -\\frac{11}{2}$"},{"key":"C","text":"$x = \\frac{1}{2}$"},{"key":"D","text":"$x = -\\frac{7}{2}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Cross-multiply to get $5(x + 1) = 3(x - 2)$. Expand both sides: $5x + 5 = 3x - 6$. Subtract $3x$ from both sides: $2x + 5 = -6$. Subtract $5$: $2x = -11$. Divide by $2$: $x = -\\frac{11}{2}$. The choice $x = \\frac{11}{2}$ drops the negative sign when solving. The choice $x = \\frac{1}{2}$ results from incorrectly setting up the cross multiplication as $5(x - 1) = 3(x + 2)$. The choice $x = -\\frac{7}{2}$ comes from an arithmetic error in combining like terms.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PU5DNG', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'Two parallel lines are cut by a transversal. One pair of alternate interior angles has measures $(9x - 17)°$ and $(5x + 31)°$. What is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$12$"},{"key":"C","text":"$48$"},{"key":"D","text":"$91$"}]$lyceon_json$::jsonb, 'B', NULL, E'Alternate interior angles formed by parallel lines and a transversal are equal, so $9x - 17 = 5x + 31$. Subtracting $5x$ from both sides gives $4x - 17 = 31$, and adding $17$ to both sides gives $4x = 48$. Dividing by $4$ yields $x = 12$. The value $6$ results from a division error when simplifying. The value $48$ comes from stopping at $4x = 48$ without dividing by $4$. The value $91$ results from substituting $x = 12$ back into the expression $9x - 17 = 91$, giving an angle measure rather than the value of $x$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PYCZZP', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'$4x + 5y = 37$ and $4x - 3y = -3$. What is the value of $x + y$?', NULL, $lyceon_json$[{"key":"A","text":"$-2$"},{"key":"B","text":"$3$"},{"key":"C","text":"$8$"},{"key":"D","text":"$12$"}]$lyceon_json$::jsonb, 'C', NULL, E'Subtracting the second equation from the first gives $(4x + 5y) - (4x - 3y) = 37 - (-3)$, which simplifies to $8y = 40$, so $y = 5$. Substituting into $4x + 5(5) = 37$ gives $4x = 12$, so $x = 3$. Therefore $x + y = 3 + 5 = 8$. The value $3$ results from stopping at $x$ without adding $y$. The value $-2$ comes from a sign error when subtracting the equations. The value $12$ arises from an arithmetic slip in the elimination step.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QGC6FS', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'If $2x^2 - 9x + 4 = 0$ and $x < 1$, what is the value of $8x^3$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '1', ARRAY['1'], E'Solve $2x^2 - 9x + 4 = 0$ using the quadratic formula: $x = \\frac{9 \\pm \\sqrt{81 - 32}}{4} = \\frac{9 \\pm \\sqrt{49}}{4} = \\frac{9 \\pm 7}{4}$. This gives $x = \\frac{16}{4} = 4$ or $x = \\frac{2}{4} = \\frac{1}{2}$. Since $x < 1$, use $x = \\frac{1}{2}$. Then $8x^3 = 8 \\left(\\frac{1}{2}\\right)^3 = 8 \\cdot \\frac{1}{8} = 1$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QRQCET', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'grid_in', E'A chemist mixes a 23% saline solution with a 47% saline solution to produce exactly 600 milliliters of a 31% saline solution. How many milliliters of the 23% saline solution does the chemist use?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '400', ARRAY['400'], E'Let $x$ be the volume (in mL) of the 23% solution and $600 - x$ the volume of the 47% solution. The total salt equation is $0.23x + 0.47(600 - x) = 0.31(600)$. Expanding: $0.23x + 282 - 0.47x = 186$, so $-0.24x = -96$, giving $x = 400$. Thus 400 mL of the 23% solution is used, and $600 - 400 = 200$ mL of the 47% solution. Verification: $0.23(400) + 0.47(200) = 92 + 94 = 186 = 0.31(600)$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RPOYII', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In triangle $PQR$, $\\angle P = (2x + 13)°$, $\\angle Q = (4x - 7)°$, and the exterior angle at vertex $R$ measures $(7x - 18)°$. What is the measure, in degrees, of $\\angle Q$?', NULL, $lyceon_json$[{"key":"A","text":"$24$"},{"key":"B","text":"$61$"},{"key":"C","text":"$89$"},{"key":"D","text":"$150$"}]$lyceon_json$::jsonb, 'C', NULL, E'By the exterior angle theorem, the exterior angle at a vertex of a triangle equals the sum of the two non-adjacent interior angles. Therefore $(2x + 13) + (4x - 7) = 7x - 18$, which simplifies to $6x + 6 = 7x - 18$. Solving gives $x = 24$. The measure of $\\angle Q$ is $4(24) - 7 = 89°$. The value $24$ is the value of $x$, not the angle measure the question asks for. The value $61$ is the measure of $\\angle P$, found from $2(24) + 13 = 61$, which is the wrong angle. The value $150$ is the exterior angle at $R$, found from $7(24) - 18 = 150$, not the interior angle $Q$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RWYN5H', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'Line $p$ has a slope of $\\frac{3}{4}$ and passes through the point $(8, 9)$. At what point does line $p$ cross the $x$-axis?', NULL, $lyceon_json$[{"key":"A","text":"$(-4, 0)$"},{"key":"B","text":"$(4, 0)$"},{"key":"C","text":"$(0, 3)$"},{"key":"D","text":"$(-3, 0)$"}]$lyceon_json$::jsonb, 'A', NULL, E'Using the point-slope form with slope $\\frac{3}{4}$ and point $(8, 9)$: $y = \\frac{3}{4}x + b$. Substituting gives $9 = \\frac{3}{4}(8) + b = 6 + b$, so $b = 3$. The equation is $y = \\frac{3}{4}x + 3$. Setting $y = 0$: $0 = \\frac{3}{4}x + 3$, so $\\frac{3}{4}x = -3$ and $x = -4$. The $x$-intercept is $(-4, 0)$. The point $(4, 0)$ results from a sign error when solving for $x$. The point $(0, 3)$ is the $y$-intercept, not the $x$-intercept. The point $(-3, 0)$ arises from an arithmetic error in the final division step.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SCVV3U', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'grid_in', E'In a right triangle, $\\sin(\\theta) = \\frac{5}{13}$, where $\\theta$ is an acute angle of the triangle. What is $\\cos(\\theta)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '12/13', ARRAY['12/13', '0.923', '.923'], E'Since $\\sin(\\theta) = \\frac{5}{13}$, the side opposite $\\theta$ is $5$ and the hypotenuse is $13$. Using the Pythagorean theorem, the adjacent side is $\\sqrt{13^2 - 5^2} = \\sqrt{169 - 25} = \\sqrt{144} = 12$. Therefore $\\cos(\\theta) = \\frac{\\text{adjacent}}{\\text{hypotenuse}} = \\frac{12}{13}$. A common error is computing $1 - \\frac{5}{13} = \\frac{8}{13}$, confusing the identity $\\sin^2 + \\cos^2 = 1$ with $\\sin + \\cos = 1$. Another error is giving $\\frac{5}{12}$, which is $\\tan(\\theta)$ rather than $\\cos(\\theta)$.', NULL, NULL, 'draft', 1, 85, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T83FSY', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'A sector of a circle has an arc length of $\\frac{49\\pi}{9}$ and a sector area of $\\frac{343\\pi}{18}$. What is the radius of the circle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Let the radius be $r$ and the central angle be $\\theta$ (in radians). The arc length formula gives $r\\theta = \\frac{49\\pi}{9}$, so $\\theta = \\frac{49\\pi}{9r}$. The sector area formula gives $\\frac{1}{2}r^2\\theta = \\frac{343\\pi}{18}$. Substituting the expression for $\\theta$: $\\frac{1}{2}r^2 \\cdot \\frac{49\\pi}{9r} = \\frac{49\\pi r}{18} = \\frac{343\\pi}{18}$. Dividing both sides by $\\frac{\\pi}{18}$ gives $49r = 343$, so $r = 7$. A common error is to divide the area by the arc length incorrectly or to confuse the sector area formula with the full circle area formula. Another error is to solve $r\\theta = \\frac{49\\pi}{9}$ for $r$ without using the second equation, leaving $r$ in terms of $\\theta$.', NULL, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UHBA8L', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $6x^3 - 9x^2 + 14x - 21$?', NULL, $lyceon_json$[{"key":"A","text":"$(3x^2 + 7)(2x - 3)$"},{"key":"B","text":"$(3x^2 - 7)(2x + 3)$"},{"key":"C","text":"$(6x^2 + 14)(x - 3)$"},{"key":"D","text":"$(2x^2 + 7)(3x - 3)$"}]$lyceon_json$::jsonb, 'A', NULL, E'Group the terms: $(6x^3 - 9x^2) + (14x - 21)$. Factor each group: $3x^2(2x - 3) + 7(2x - 3)$. Since both groups share the common factor $(2x - 3)$, factor it out to get $(3x^2 + 7)(2x - 3)$. The choice $(3x^2 - 7)(2x + 3)$ uses incorrect signs for both the constant in the first factor and the constant in the second factor. The choice $(6x^2 + 14)(x - 3)$ incorrectly factors $6x^3 + 14x$ and $-9x^2 - 21$ but loses the correct grouping. The choice $(2x^2 + 7)(3x - 3)$ expands to $6x^3 - 6x^2 + 21x - 21$, which does not match the original expression.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UHZJKM', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A ceramic glaze recipe requires 5 parts feldspar for every 3 parts silica by weight. If a potter uses 45 grams of silica, how many grams of feldspar are needed?', NULL, $lyceon_json$[{"key":"A","text":"27"},{"key":"B","text":"60"},{"key":"C","text":"75"},{"key":"D","text":"120"}]$lyceon_json$::jsonb, 'C', NULL, E'The ratio of feldspar to silica is $\\frac{5}{3}$. With 45 grams of silica, the feldspar needed is $\\frac{5}{3} \\times 45 = 75$ grams. The value 27 results from inverting the ratio to $\\frac{3}{5} \\times 45 = 27$, which gives the wrong component. The value 60 comes from a multiplication error when scaling the ratio. The value 120 results from calculating the total mixture weight using $\\frac{5 + 3}{3} \\times 45 = 120$ instead of the feldspar portion alone.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UOKLIF', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'grid_in', E'When $2x^3 - 5x^2 + 3x - 7$ is divided by $(x - 3)$, what is the remainder?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11', ARRAY['11'], E'By the Remainder Theorem, the remainder when a polynomial $p(x)$ is divided by $(x - a)$ equals $p(a)$. Here $a = 3$, so evaluate $p(3) = 2(3)^3 - 5(3)^2 + 3(3) - 7 = 2(27) - 5(9) + 9 - 7 = 54 - 45 + 9 - 7 = 11$. The remainder is $11$.', NULL, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W8AI4G', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A researcher models the relationship between the amount of fertilizer $x$ (in grams) and plant height $y$ (in centimeters) with the equation $y = -0.3x^2 + 8.4x + 11$. According to this model, what amount of fertilizer, in grams, results in the maximum plant height?', NULL, $lyceon_json$[{"key":"A","text":"$8.4$"},{"key":"B","text":"$11$"},{"key":"C","text":"$14$"},{"key":"D","text":"$28$"}]$lyceon_json$::jsonb, 'C', NULL, E'The equation $y = -0.3x^2 + 8.4x + 11$ is a downward-opening parabola, so the vertex gives the maximum height. The $x$-coordinate of the vertex is $x = \\frac{-b}{2a} = \\frac{-8.4}{2(-0.3)} = \\frac{-8.4}{-0.6} = 14$ grams. The value $8.4$ mistakes the coefficient of $x$ for the optimal input rather than applying the vertex formula. The value $11$ confuses the constant term (the $y$-intercept) with the $x$-value at the vertex. The value $28$ results from using $\\frac{-b}{a} = \\frac{-8.4}{-0.3} = 28$, omitting the factor of 2 in the denominator.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W9LC98', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $p(x) = -3x^5 + 7x^3 - 2x$ is defined for all real numbers. As $x$ increases without bound, which of the following best describes the behavior of $p(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$p(x)$ increases without bound"},{"key":"B","text":"$p(x)$ approaches $0$"},{"key":"C","text":"$p(x)$ approaches $-3$"},{"key":"D","text":"$p(x)$ decreases without bound"}]$lyceon_json$::jsonb, 'D', NULL, E'The end behavior of a polynomial is determined by its leading term. Here the leading term is $-3x^5$. Since the degree is odd and the leading coefficient is negative, as $x$ increases without bound, $p(x)$ decreases without bound. Choosing that $p(x)$ increases without bound ignores the negative leading coefficient. Stating that $p(x)$ approaches $0$ applies the behavior of rational functions, not polynomials. Stating that $p(x)$ approaches $-3$ mistakes the leading coefficient for a horizontal asymptote.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XVMQT2', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangular prism has a length of $7$ inches, a width of $3$ inches, and a height of $11$ inches. What is the volume, in cubic inches, of the rectangular prism?', NULL, $lyceon_json$[{"key":"A","text":"$21$"},{"key":"B","text":"$77$"},{"key":"C","text":"$231$"},{"key":"D","text":"$462$"}]$lyceon_json$::jsonb, 'C', NULL, E'The volume of a rectangular prism is $V = l \\times w \\times h$. Substituting the given dimensions: $V = 7 \\times 3 \\times 11 = 231$ cubic inches. The value $21$ results from multiplying only the length and width ($7 \\times 3$) and omitting the height. The value $77$ comes from multiplying only the length and height ($7 \\times 11$), computing the area of one face rather than the full volume. The value $462$ doubles the correct volume, an arithmetic error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YANYDS', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'For the linear function $f$, $f(2) = -5$ and $f(6) = 19$. The function $g$ is defined by $g(x) = f(x + 3) - 4$. What is $g(0)$?', NULL, $lyceon_json$[{"key":"A","text":"$1$"},{"key":"B","text":"$-3$"},{"key":"C","text":"$-21$"},{"key":"D","text":"$3$"}]$lyceon_json$::jsonb, 'B', NULL, E'The slope of $f$ is $\\frac{19 - (-5)}{6 - 2} = \\frac{24}{4} = 6$. Using the point $(2, -5)$: $f(x) = 6x - 17$. Then $g(0) = f(0 + 3) - 4 = f(3) - 4 = (6 \\cdot 3 - 17) - 4 = 1 - 4 = -3$. The value $1$ comes from computing $f(3) = 1$ but forgetting to subtract $4$. The value $-21$ results from evaluating $f(0) - 4 = -17 - 4 = -21$, using $f(0)$ instead of $f(0 + 3)$. The value $3$ is a sign error on the correct answer.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YPBXTF', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'In a right triangle, $\\sin(\\theta) = \\frac{3}{5}$, where $\\theta$ is an acute angle, and the perimeter of the triangle is $48$. What is the area of the triangle?', NULL, $lyceon_json$[{"key":"A","text":"$24$"},{"key":"B","text":"$96$"},{"key":"C","text":"$120$"},{"key":"D","text":"$192$"}]$lyceon_json$::jsonb, 'B', NULL, E'Since $\\sin(\\theta) = \\frac{3}{5}$, the sides of the right triangle are proportional to $3$, $4$, and $5$ (where $4 = \\sqrt{5^2 - 3^2}$). The perimeter is $3k + 4k + 5k = 12k = 48$, so $k = 4$. The legs are $12$ and $16$, and the hypotenuse is $20$. The area is $\\frac{1}{2}(12)(16) = 96$. The value $24$ results from scaling the base-case area $\\frac{1}{2}(3)(4) = 6$ by $k = 4$ linearly, giving $6 \\times 4 = 24$, instead of scaling by $k^2 = 16$ to get $6 \\times 16 = 96$. The value $120$ comes from using the hypotenuse in the area formula as $\\frac{1}{2}(12)(20) = 120$, but area requires the two legs, not a leg and the hypotenuse. The value $192$ results from omitting the $\\frac{1}{2}$ factor: $12 \\times 16 = 192$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z4BUZU', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'For what value of $k$ does the system of equations $y = 2x^2 - 5x + k$ and $y = 3x - 7$ have exactly one real solution?', NULL, $lyceon_json$[{"key":"A","text":"$k = 1$"},{"key":"B","text":"$k = -1$"},{"key":"C","text":"$k = 8$"},{"key":"D","text":"$k = 15$"}]$lyceon_json$::jsonb, 'A', NULL, E'Set the two expressions for $y$ equal: $2x^2 - 5x + k = 3x - 7$. Rearrange to $2x^2 - 8x + (k + 7) = 0$. For exactly one real solution, the discriminant must equal zero: $(-8)^2 - 4(2)(k + 7) = 0$, which gives $64 - 8(k + 7) = 0$. Expand to $64 - 8k - 56 = 0$, so $8 - 8k = 0$ and $k = 1$. The choice $k = -1$ results from a sign error when solving $8 - 8k = 0$. The choice $k = 8$ comes from omitting the constant $7$ and solving $64 - 8k = 0$ directly. The choice $k = 15$ arises from incorrectly rearranging the equation as $2x^2 - 8x + (k - 7) = 0$ and solving $64 - 8(k - 7) = 0$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZIDO8P', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A data set contains the following 9 values listed in order from least to greatest: 14, 17, 17, 19, 23, 23, 23, 29, 31. What is the median of this data set?', NULL, $lyceon_json$[{"key":"A","text":"17"},{"key":"B","text":"19"},{"key":"C","text":"22"},{"key":"D","text":"23"}]$lyceon_json$::jsonb, 'D', NULL, E'With 9 values, the median is the $\\frac{9 + 1}{2} = 5$th value in order. Counting from least to greatest, the 5th value is 23. The value 17 confuses the median with a frequently appearing value near the lower end of the set. The value 19 results from selecting the 4th value instead of the 5th. The value 22 comes from computing the mean $\\frac{14 + 17 + 17 + 19 + 23 + 23 + 23 + 29 + 31}{9} = \\frac{196}{9} \\approx 21.8$ and rounding, which confuses the median with the mean.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZTASXU', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'A factory produces widgets. Each widget requires 3 hours of labor and 2 pounds of raw material. The factory has at most 171 hours of labor and at most 100 pounds of raw material available per week. The factory must produce at least 11 widgets per week to fulfill a standing contract. Which system of inequalities represents these constraints, where $w$ is the number of widgets produced per week?', NULL, $lyceon_json$[{"key":"A","text":"$3w \\leq 171$, $2w \\leq 100$, $w \\geq 11$"},{"key":"B","text":"$3w \\geq 171$, $2w \\geq 100$, $w \\geq 11$"},{"key":"C","text":"$3w \\leq 171$, $2w \\leq 100$, $w \\leq 11$"},{"key":"D","text":"$2w \\leq 171$, $3w \\leq 100$, $w \\geq 11$"}]$lyceon_json$::jsonb, 'A', NULL, E'Each widget uses 3 hours, so $w$ widgets use $3w$ hours, which cannot exceed 171: $3w \\leq 171$. Each widget uses 2 pounds, so $2w \\leq 100$. The contract requires at least 11 widgets: $w \\geq 11$. The system $3w \\geq 171$, $2w \\geq 100$, $w \\geq 11$ reverses the resource constraints, requiring usage to be at least the available amounts rather than at most. The system with $w \\leq 11$ misinterprets "at least 11" as "at most 11." The system $2w \\leq 171$, $3w \\leq 100$ swaps the coefficients for labor and material.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20FBDM4', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Marine biologists studying the deep-sea anglerfish Melanocetus johnsonii have long noted the species'' extreme sexual dimorphism: males are roughly one-tenth the size of females. A 2019 survey of 47 specimens collected near the Azores confirmed that this size disparity holds across the entire sampled population, with no overlap between male and female body-length distributions. The researchers concluded that the dimorphism is not an artifact of selective sampling but a fixed trait of the species.', $lyceon_json$[{"key":"A","text":"A survey confirmed that sexual dimorphism in Melanocetus johnsonii is a consistent species-level trait rather than a sampling artifact."},{"key":"B","text":"Deep-sea anglerfish collected near the Azores were found to be significantly smaller than specimens collected in other ocean regions."},{"key":"C","text":"Researchers discovered that male and female anglerfish inhabit different depth ranges, which accounts for the observed size differences between the sexes."},{"key":"D","text":"The extreme size disparity between male and female Melanocetus johnsonii has prompted marine biologists to reclassify the species into two separate taxonomic groups."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes a survey that confirmed the extreme sexual dimorphism in Melanocetus johnsonii is a fixed trait, not a sampling artifact. The choice stating the survey confirmed dimorphism as a consistent species-level trait captures this main idea. The choice about specimens being smaller near the Azores misreads the passage, which compares males to females, not regional populations. The choice about different depth ranges introduces information not present in the text. The choice about reclassification into two taxonomic groups goes well beyond the passage''s conclusion.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21EPRUX', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding from Okafor''s study, if true, would most directly undermine the traditional explanation described in the text?', E'Geologists have traditionally attributed the high mineral diversity found in certain volcanic island soils to repeated eruptions depositing chemically distinct lava layers over millennia. Each eruption, the reasoning goes, introduces a different mineral suite depending on the magma''s composition at the time. Geochemist Adaeze Okafor, however, suspects that post-depositional weathering -- chemical reactions between rainwater, atmospheric gases, and the original basalt -- accounts for most of the observed mineral variety. To investigate, Okafor analyzed mineral compositions in soil cores from Isla Quemada, a volcanic island that formed from a single eruption event 11,000 years ago and has experienced no subsequent volcanic activity.', $lyceon_json$[{"key":"A","text":"The Isla Quemada soil cores contained a mineral diversity comparable to that of multi-eruption volcanic islands despite the island's origin from only one eruption event."},{"key":"B","text":"The mineral composition of Isla Quemada's soil closely matched the mineral composition of the original basalt from the single eruption, with very little chemical alteration evident."},{"key":"C","text":"Multi-eruption volcanic islands in the same ocean basin showed significantly greater mineral diversity than Isla Quemada across all sampled soil depths."},{"key":"D","text":"Rainfall levels on Isla Quemada were substantially lower than on nearby multi-eruption islands, which could reduce the rate of chemical weathering in the island's soil over time."}]$lyceon_json$::jsonb, 'A', NULL, E'The traditional explanation holds that mineral diversity requires multiple chemically distinct eruptions. If a single-eruption island shows comparable mineral diversity, then repeated eruptions are not necessary for that diversity, directly undermining the traditional view and supporting Okafor''s weathering hypothesis. The finding that the soil closely matches the original basalt with little alteration would actually support the traditional explanation by suggesting weathering has not produced new minerals. The finding that multi-eruption islands have greater diversity than Isla Quemada would be consistent with the traditional view rather than undermining it. The finding about lower rainfall on Isla Quemada addresses a confounding variable but does not directly challenge the eruption-based explanation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21GMK1K', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Geologist Maria Tavares has argued that the basalt formations along the Faroe Islands coastline were shaped primarily by glacial erosion during the last ice age. _______ geochemist Henrik Lindqvist contends that the formations owe their distinctive columnar structure to the cooling rate of volcanic lava flows, a process unrelated to glaciation.', $lyceon_json$[{"key":"A","text":"To support this interpretation,"},{"key":"B","text":"Similarly,"},{"key":"C","text":"However,"},{"key":"D","text":"For this reason,"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct transition is "However," which signals a contrast between Tavares''s glacial-erosion explanation and Lindqvist''s competing volcanic-cooling explanation. "To support this interpretation" wrongly implies that Lindqvist''s claim reinforces Tavares''s, when it actually contradicts it. "Similarly" suggests agreement between the two geologists, but their positions are opposed. "For this reason" implies that Lindqvist''s claim is a consequence of Tavares''s argument, but the two explanations are independent and contradictory.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23OTMMZ', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'While writing an article about bioluminescence for a science magazine, a student wants to present a finding that challenges a commonly held assumption about the function of bioluminescence in deep-sea organisms. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29AR79K', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'The monarch butterfly migrates up to 3,000 miles each autumn from Canada to central Mexico. _______ the butterflies cluster on oyamel fir trees at densities exceeding 10 million per acre, relying on the forest canopy to insulate them from freezing temperatures.', $lyceon_json$[{"key":"A","text":"Upon arriving at their wintering grounds,"},{"key":"B","text":"In contrast to this migration pattern,"},{"key":"C","text":"As a result of declining populations,"},{"key":"D","text":"Prior to beginning this journey,"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct transition, "Upon arriving at their wintering grounds," logically connects the first sentence about the autumn migration to the second sentence describing what the butterflies do once they reach Mexico. "In contrast to this migration pattern" incorrectly signals opposition when the second sentence continues describing the same migratory behavior. "As a result of declining populations" introduces a causal relationship about population decline that is not supported by the passage. "Prior to beginning this journey" reverses the chronological sequence, since the second sentence describes what happens after the migration, not before it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BGABLS', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the underlined sentence in the overall structure of the text?', E'The philosopher Martha Nussbaum has argued that literature cultivates moral reasoning more effectively than abstract ethical theory. In her view, novels demand that readers inhabit perspectives radically unlike their own, exercising a form of empathetic imagination that no syllogism can replicate. <u>Critics such as Richard Posner have countered that avid readers of fiction show no measurable advantage in ethical behavior compared to non-readers, pointing to psychological studies that found no correlation between literary consumption and prosocial conduct.</u> Nussbaum has responded that Posner conflates moral sensitivity -- the capacity to perceive ethical complexity -- with moral action, which is shaped by countless factors beyond perception alone.', $lyceon_json$[{"key":"A","text":"It qualifies Nussbaum's claim by acknowledging a limitation she herself identified in her original argument about literature"},{"key":"B","text":"It presents an empirical objection to Nussbaum's position that the passage subsequently addresses with a conceptual distinction"},{"key":"C","text":"It offers additional evidence in support of Nussbaum's central thesis about literature and moral reasoning"},{"key":"D","text":"It shifts the focus of the passage from the philosophical merits of Nussbaum's argument to its practical implications for educational curriculum reform"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is the choice stating that the sentence presents an empirical objection addressed by a conceptual distinction. The underlined sentence introduces Posner''s counterargument, which relies on psychological studies finding no behavioral correlation -- an empirical challenge. The final sentence then shows Nussbaum rebutting this by distinguishing moral sensitivity from moral action, a conceptual distinction that reframes the terms of the debate. The choice about Nussbaum acknowledging her own limitation is incorrect because the objection comes from Posner, not from Nussbaum herself. The choice about offering additional support for Nussbaum''s thesis is incorrect because the sentence explicitly opposes her position by citing evidence against it. The choice about shifting to educational curriculum reform is incorrect because the passage never mentions education policy; the discussion remains within the philosophical debate about literature and moral reasoning.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2C66ESR', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'By the time the restoration team finished reinforcing the cathedral''s flying buttresses in 2019, cracks in the limestone ______ visible for nearly a decade, having first appeared shortly after the earthquake of 2010.', $lyceon_json$[{"key":"A","text":"have been"},{"key":"B","text":"had been"},{"key":"C","text":"were"},{"key":"D","text":"would have been"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct choice is "had been" because the past perfect tense is required to indicate that the cracks were visible for a duration of time before another past event, the completion of the restoration in 2019. The construction "By the time... finished" signals that one past action preceded another, which is precisely what the past perfect conveys. The choice "have been" uses the present perfect, which connects a past event to the present moment rather than to another point in the past. The choice "were" uses the simple past, which fails to express the temporal relationship between the decade of visibility and the restoration''s completion. The choice "would have been" introduces a conditional mood, implying a hypothetical scenario rather than describing events that actually occurred.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EUDQRP', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the overall structure of the text?', E'The axolotl, a salamander native to Lake Xochimilco in Mexico, possesses a remarkable biological trait: it can regenerate entire limbs, portions of its heart, and even sections of its brain. <u>Scientists have studied axolotls in laboratories since the 1860s, making them one of the longest-running model organisms in regenerative biology.</u> Current research focuses on identifying the specific genes that activate the regeneration process, with the hope of eventually applying these findings to human medicine.', $lyceon_json$[{"key":"A","text":"It provides historical context for the scientific interest described in the passage"},{"key":"B","text":"It challenges a commonly held assumption about the axolotl's regenerative abilities"},{"key":"C","text":"It presents a finding that directly contradicts earlier research on the axolotl"},{"key":"D","text":"It proposes a new experimental methodology for studying limb regeneration in amphibians"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating that the sentence provides historical context. The underlined sentence places axolotl research in a timeline beginning in the 1860s, situating the current genetic research described afterward within a longer scientific tradition. The choice about challenging an assumption is incorrect because the sentence affirms the importance of axolotl research rather than disputing any claim. The choice about contradicting earlier research is incorrect because the sentence describes continuity of study, not conflict between findings. The choice about proposing a new methodology is incorrect because the sentence recounts the history of existing research rather than introducing any new experimental approach.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EUDT7G', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'In 1953, the psychologist B. F. Skinner proposed that language acquisition in children is driven entirely by reinforcement: caregivers reward correct utterances and ignore or correct errors, shaping the child''s verbal behavior over time. Linguist Noam Chomsky challenged this view in 1959, arguing that children regularly produce grammatical structures they have never heard, such as novel sentence combinations and overgeneralized verb forms like "goed" instead of "went." Chomsky contended that these creative errors point to an innate grammatical capacity that reinforcement alone cannot explain.', $lyceon_json$[{"key":"A","text":"Chomsky argued that children's production of novel grammatical forms undermines Skinner's claim that reinforcement alone drives language acquisition."},{"key":"B","text":"Skinner and Chomsky ultimately reached a consensus that both reinforcement and innate capacity play equally important roles in how children learn language."},{"key":"C","text":"Chomsky's 1959 critique demonstrated conclusively that reinforcement plays absolutely no role in the way children acquire language skills over time."},{"key":"D","text":"Skinner's reinforcement model accurately predicted most patterns of language acquisition, though it could not account for certain rare grammatical errors children make."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents Skinner''s reinforcement theory and Chomsky''s challenge to it, centering on Chomsky''s argument that children''s creative grammatical errors reveal an innate capacity reinforcement cannot explain. The choice stating Chomsky argued that novel grammatical forms undermine the reinforcement-only claim captures this central idea. The choice about a consensus between the two misrepresents the passage, which describes a disagreement with no resolution mentioned. The choice claiming Chomsky showed reinforcement plays no role overstates his argument; he contended reinforcement alone is insufficient, not that it is irrelevant. The choice characterizing Skinner''s model as mostly accurate contradicts the passage''s framing, which presents Chomsky''s critique as a substantial challenge.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EW4T9L', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Which choice best describes a fundamental point of disagreement between the authors of the two texts?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FL636B', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The collection of rare manuscripts housed in the university''s underground vault ______ available to researchers only by special appointment.', $lyceon_json$[{"key":"A","text":"are"},{"key":"B","text":"is"},{"key":"C","text":"have been"},{"key":"D","text":"were being"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct choice is "is" because the subject of the sentence is "collection," which is singular. Although the prepositional phrase "of rare manuscripts" contains a plural noun, the verb must agree with the head noun "collection," not with the object of the preposition. The choice "are" incorrectly uses a plural verb, likely resulting from confusion between the subject and the nearer plural noun "manuscripts." The choice "have been" also uses a plural auxiliary and introduces an unnecessary shift to the present perfect tense. The choice "were being" uses a plural past progressive form that disagrees with the singular subject and introduces an illogical tense shift in context.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2I69HW3', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Neuroscientist Priya Chandrasekaran studied decision-making in foraging honeybees by placing two identical sugar-water feeders at different distances from a hive: one at 200 meters and one at 900 meters. Both feeders offered the same 40% sucrose concentration. Over 14 days, 78% of marked foragers consistently visited the nearer feeder, even when the distant feeder was temporarily unoccupied and offered no competition. However, when Chandrasekaran raised the distant feeder''s concentration to 60% sucrose, the proportion of foragers visiting it rose to 53% within three days. Chandrasekaran concluded that foraging honeybees ________', $lyceon_json$[{"key":"A","text":"weigh distance costs against reward quality, shifting their foraging preferences when a richer resource sufficiently compensates for the greater travel expenditure."},{"key":"B","text":"are unable to detect differences in sucrose concentration below a certain threshold and therefore default to visiting the nearest available food source."},{"key":"C","text":"rely primarily on pheromone signals from returning foragers rather than on direct assessment of distance when selecting which feeder to visit."},{"key":"D","text":"will always prefer a closer food source regardless of reward quality because the energy cost of longer flights outweighs any possible nutritional benefit from richer sucrose solutions."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage shows bees initially preferring the nearer feeder but shifting to the distant one when its concentration increased, demonstrating a trade-off between distance and reward. The choice about weighing distance costs against reward quality captures this trade-off. The choice about bees being unable to detect concentration differences is unsupported; the passage shows they responded to the concentration change. The choice about pheromone signals introduces a mechanism not discussed in the passage. The choice claiming bees always prefer the closer source regardless of reward is directly contradicted by the shift to the distant feeder when concentration increased.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LDN2KK', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the findings presented in Text 1?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LR5MQD', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the text, what does the underlined word most nearly mean?', E'Recent neuroscience research has demonstrated that the adult human brain is far more <u>plastic</u> than scientists once believed. A 2019 longitudinal study tracked participants who learned to juggle over a three-month period and found measurable increases in gray matter density in regions associated with visual-motor coordination, suggesting that sustained practice can physically reshape neural architecture well into middle age.', $lyceon_json$[{"key":"A","text":"Synthetic"},{"key":"B","text":"Rigid"},{"key":"C","text":"Malleable"},{"key":"D","text":"Transparent"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is "Malleable." The passage describes the brain''s capacity to physically change its structure in response to new learning, as evidenced by measurable increases in gray matter density. "Malleable" means capable of being shaped or altered, which directly captures this meaning. "Synthetic" means artificially produced, which produces an incoherent claim -- the passage is not arguing the brain is artificial. "Rigid" means inflexible and unable to change, which directly contradicts the passage''s central point that the brain reshapes itself through practice. "Transparent" means see-through or easily understood, neither sense of which applies to the passage''s discussion of structural neural change.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MT27P9', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the text, what does the underlined word most nearly mean?', E'In the 1890s, the germ theory of disease was still gaining <u>currency</u> among rural physicians. Many practitioners outside major cities continued to attribute illness to miasma -- noxious vapors believed to emanate from decaying matter -- despite mounting laboratory evidence linking specific microorganisms to infectious diseases.', $lyceon_json$[{"key":"A","text":"Denomination"},{"key":"B","text":"Acceptance"},{"key":"C","text":"Revenue"},{"key":"D","text":"Legislation"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is "Acceptance." The passage describes germ theory gradually becoming more widely believed among rural physicians, so "gaining currency" means gaining acceptance or prevalence. Substituting "acceptance" preserves the meaning: "gaining acceptance among rural physicians." "Denomination" refers to a unit of money or a religious group, neither of which makes sense when applied to a scientific theory gaining ground. "Revenue" means income, producing the incoherent phrase "gaining revenue among rural physicians." "Legislation" refers to laws, which cannot logically describe how a scientific theory spreads among doctors.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OQZW5R', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The paleontologist explained why the fossil bed was so ______ it contained the remains of seventeen distinct species from the late Cretaceous period, including three that had never been documented.', $lyceon_json$[{"key":"A","text":"remarkable, it"},{"key":"B","text":"remarkable it"},{"key":"C","text":"remarkable: it"},{"key":"D","text":"remarkable. Because it"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct choice is "remarkable: it" because a colon appropriately introduces an explanation or elaboration of the preceding clause. The text before the blank states that the fossil bed was remarkable, and the text after the blank explains why it was remarkable. The choice "remarkable, it" creates a comma splice by joining two independent clauses with only a comma. The choice "remarkable it" produces a run-on sentence with no punctuation between the clauses. The choice "remarkable. Because it" creates a sentence fragment, since "Because it contained the remains of seventeen distinct species" is a dependent clause that cannot stand alone as a sentence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PNOSMZ', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'While writing a report on the history of cartography, a student wants to contrast early mapmaking methods with modern techniques. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PSFB8B', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the text, what does the underlined word most nearly mean?', E'The <u>celebrated</u> entomologist Dr. Maren Okoro spent over seventeen years cataloging beetle species in the cloud forests of central Ecuador. Her meticulous taxonomic work identified thirty-one species previously unknown to science, earning her recognition from conservation organizations across South America.', $lyceon_json$[{"key":"A","text":"Renowned"},{"key":"B","text":"Festive"},{"key":"C","text":"Inexperienced"},{"key":"D","text":"Controversial"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is "Renowned." The passage describes Dr. Okoro''s extensive seventeen-year career and her significant scientific contributions, indicating that she is well-known and respected in her field. Substituting "renowned" produces a coherent sentence: "The renowned entomologist." "Festive" means relating to celebration or merrymaking, which produces an incoherent description of a scientist. "Inexperienced" contradicts the passage''s emphasis on her seventeen years of work. "Controversial" implies dispute or disagreement, which is unsupported by the passage''s entirely positive description of her achievements.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QMKHL0', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Dr. Vasquez has studied bioluminescent organisms in deep ocean trenches for over a ______ her research has revealed several previously unknown species of jellyfish.', $lyceon_json$[{"key":"A","text":"decade, her"},{"key":"B","text":"decade her"},{"key":"C","text":"decade. Her"},{"key":"D","text":"decade, having her"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct choice is "decade. Her" because the text contains two independent clauses: "Dr. Vasquez has studied bioluminescent organisms in deep ocean trenches for over a decade" and "Her research has revealed several previously unknown species of jellyfish." A period properly separates these two complete sentences. The choice "decade, her" creates a comma splice, incorrectly joining two independent clauses with only a comma. The choice "decade her" produces a run-on sentence with no punctuation between the clauses. The choice "decade, having her" creates an ungrammatical construction because "having her research has revealed" does not form a coherent participial phrase.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QTIR97', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a research article would most effectively support the claim that bilingual speakers exhibit cognitive advantages in task-switching scenarios?', E'Some cognitive scientists argue that bilingual individuals develop enhanced executive-function skills because managing two languages requires constant monitoring and switching between linguistic systems. This ongoing mental juggling, proponents claim, strengthens the brain''s ability to shift between tasks efficiently, even in non-linguistic contexts.', $lyceon_json$[{"key":"A","text":"\"Bilingual participants completed the color-shape switching task with an average transition cost of 142 milliseconds, compared to 213 milliseconds for matched monolingual controls, a statistically significant difference.\""},{"key":"B","text":"\"Both bilingual and monolingual participants performed equally well on sustained-attention tasks requiring focus on a single visual stimulus over a prolonged period of uninterrupted observation.\""},{"key":"C","text":"\"Participants who reported speaking two languages at home were more likely to express a preference for multicultural social environments in the follow-up survey.\""},{"key":"D","text":"\"Neuroimaging revealed that bilingual speakers showed greater gray-matter density in the left inferior parietal lobule, a region associated with language processing and vocabulary storage.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The claim is about bilingual speakers having cognitive advantages specifically in task-switching. The quotation reporting that bilingual participants completed a switching task faster than monolinguals directly supports this claim with measurable data. The quotation about equal performance on sustained-attention tasks addresses a different cognitive domain and does not support a task-switching advantage. The quotation about preferences for multicultural environments describes social attitudes, not cognitive performance. The quotation about gray-matter density relates to brain structure associated with language processing, not to task-switching performance.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RBTI8J', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Researchers at a botanical garden tested whether ambient music affects plant growth rates. They exposed 30 tomato seedlings to classical music for 8 hours daily and kept 30 genetically identical seedlings in silence as a control. After 6 weeks, the music-exposed group showed an average stem height of 23.7 centimeters, while the control group averaged 23.4 centimeters -- a difference the researchers found to be statistically insignificant. The researchers therefore concluded that ________', $lyceon_json$[{"key":"A","text":"classical music does not produce a measurable effect on tomato seedling growth under the conditions tested."},{"key":"B","text":"ambient noise of any kind is unlikely to influence the growth patterns of plants in general."},{"key":"C","text":"the tomato seedlings exposed to music grew slightly taller because they benefited from the sound vibrations."},{"key":"D","text":"the experimental design was flawed because the sample size of 30 seedlings per group was insufficient for reliable statistical analysis of growth patterns."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states the height difference between the two groups was statistically insignificant, so the logical conclusion is that classical music did not produce a measurable effect under these conditions. The choice about ambient noise and plants in general overgeneralizes far beyond the study''s scope, which tested only classical music on tomato seedlings. The choice claiming the music group benefited from vibrations contradicts the passage''s finding of no significant difference. The choice about a flawed design introduces a criticism the researchers did not make and is unsupported by the text.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RJUJAG', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Agricultural scientists at a university in the Netherlands hypothesized that crop fields bordering wildflower strips have higher yields than isolated fields because the wildflower strips attract pollinating insects. To test this, the researchers compared wheat yields -- wheat being a wind-pollinated crop that does not depend on insect pollinators -- in fields adjacent to wildflower strips and fields without such borders.', $lyceon_json$[{"key":"A","text":"Wheat yields were nearly identical in both groups of fields, showing no significant benefit from proximity to the wildflower strips."},{"key":"B","text":"Fields adjacent to wildflower strips produced substantially more wheat per hectare than the isolated fields over the three-year study period."},{"key":"C","text":"The wildflower strips attracted a diverse community of insect species, including both pollinators and agricultural pest predators."},{"key":"D","text":"Farmers who planted wildflower strips reported higher overall satisfaction with their land management practices compared to those who did not."}]$lyceon_json$::jsonb, 'A', NULL, E'The hypothesis is that wildflower strips boost yields specifically because they attract pollinators. The researchers tested this by using wheat, which does not need insect pollination. If wheat yields are identical regardless of proximity to wildflower strips, it supports the claim that the yield benefit seen in other crops comes from pollination specifically -- not from some other factor. The choice about wheat yields being higher would actually undermine the hypothesis by suggesting a non-pollination mechanism is at work. The choice about diverse insect species describes the strips'' ecological effect but does not address whether pollination is the mechanism for yield increases. The choice about farmer satisfaction is irrelevant to the pollination hypothesis.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
