INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VBNBRF', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'While writing an overview of bark beetle ecology for a general audience, a student wants to emphasize the economic damage caused by bark beetles. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WDM870', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the function of the underlined sentence in the overall structure of the text?', E'Historians have long debated whether the construction of the Great Wall of China served primarily as a military fortification or as a tool of economic regulation. While the wall''s watchtowers and garrison stations suggest defensive intent, recent archaeological evidence reveals extensive customs infrastructure along key segments. <u>Excavations at Juyongguan Pass uncovered clay seals, merchant ledgers, and standardized weight measures dating to the Ming dynasty, none of which would be expected at a purely military installation.</u> This evidence has prompted some scholars to argue that the wall functioned as much as a border checkpoint for trade as a barrier against invasion.', $lyceon_json$[{"key":"A","text":"It introduces the central historiographic debate that the remainder of the passage attempts to resolve"},{"key":"B","text":"It summarizes the final conclusion that scholars have drawn from the archaeological findings presented"},{"key":"C","text":"It provides specific evidence supporting the claim that the wall had an economic function"},{"key":"D","text":"It explains why earlier historians regarded the wall as primarily a military fortification rather than a trade checkpoint"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is the choice stating that the sentence provides specific evidence for an economic function. The underlined sentence lists concrete archaeological artifacts -- clay seals, merchant ledgers, and standardized weight measures -- and explicitly notes these items would not be found at a purely military site, directly supporting the economic-regulation interpretation. The choice about introducing the central debate is incorrect because the debate is introduced in the first sentence, before the underlined portion. The choice about summarizing a final conclusion is incorrect because the sentence presents raw evidence rather than a scholarly conclusion; the conclusion appears in the sentence that follows it. The choice about explaining earlier military interpretations is incorrect because the sentence describes newly discovered trade-related artifacts, not the reasoning behind older military interpretations.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WSG6YH', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Historian Mariana Espinoza examined municipal tax records from three colonial-era silver mining towns in the Andes between 1680 and 1740. She found that during periods when silver ore yields declined sharply, local tax revenues from commerce actually increased. Espinoza attributes this pattern to the diversification of economic activity: as mining became less profitable, residents turned to textile production and regional trade. The finding suggests that ________', $lyceon_json$[{"key":"A","text":"colonial mining communities could adapt economically to declining ore yields by expanding into alternative industries like textile manufacturing and trade."},{"key":"B","text":"silver mining in the Andes was ultimately less profitable than textile production throughout the entire colonial period from the sixteenth to eighteenth centuries."},{"key":"C","text":"the colonial-era tax system in the Andes was designed to incentivize economic diversification during periods of reduced mining output."},{"key":"D","text":"municipal tax records are generally unreliable indicators of actual economic conditions in colonial mining communities."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes communities shifting to textile production and trade when mining declined, with commerce tax revenues rising as a result. The logical inference is that these communities could adapt by expanding into alternative industries. The choice claiming mining was less profitable than textiles throughout the entire colonial period overgeneralizes from a specific pattern during yield declines. The choice about the tax system being designed to incentivize diversification attributes intentional design to the tax system, which the passage does not support. The choice calling tax records unreliable contradicts the passage, which uses those records as credible evidence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Y2QORN', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'A 2022 study found that urban green roofs reduced building cooling costs by an average of 26% during summer months. The researchers attributed this effect to the insulating properties of the soil substrate and the evapotranspiration from plant cover. _______ a follow-up analysis revealed that the cost savings diminished sharply in buildings taller than eleven stories, where wind exposure stripped moisture from the rooftop vegetation faster than it could be replenished.', $lyceon_json$[{"key":"A","text":"In other words,"},{"key":"B","text":"Consequently,"},{"key":"C","text":"Nonetheless,"},{"key":"D","text":"To illustrate this point,"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct transition is "Nonetheless," which signals a concession: although the earlier findings showed significant cooling-cost savings, the follow-up analysis introduced a complicating limitation (diminished savings in taller buildings). "In other words" would signal a restatement, but the follow-up analysis introduces new and contrasting information rather than rephrasing the original finding. "Consequently" implies the follow-up result is a direct effect of the cooling savings, but the diminished savings are a qualification of those findings, not a consequence of them. "To illustrate this point" suggests the follow-up analysis provides an example supporting the 26% savings claim, when it actually reveals a condition under which those savings do not hold.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 85, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZG5OFO', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The grant committee requires that each applicant ______ a detailed proposal outlining both the methodology and the expected societal impact of the research before any funding decision is made.', $lyceon_json$[{"key":"A","text":"submits"},{"key":"B","text":"submit"},{"key":"C","text":"will submit"},{"key":"D","text":"would submit"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct choice is "submit" because the verb "requires" triggers the mandative subjunctive mood in the subordinate "that" clause. In Standard English, verbs of demand, recommendation, or requirement govern a "that" clause whose verb takes the bare subjunctive form, the base form without inflection, regardless of the subject''s number. Thus "requires that each applicant submit" is correct even though "each applicant" is singular. The choice "submits" incorrectly uses the indicative mood, adding the third-person singular "-s" ending where the subjunctive demands the uninflected base form. The choice "will submit" incorrectly introduces the future tense, which is not used in mandative subjunctive constructions. The choice "would submit" incorrectly uses the conditional mood, suggesting a hypothetical situation rather than expressing a requirement.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZTL8MM', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The archaeologist, whose excavation of a Bronze Age settlement near the Danube had already yielded over three hundred ______ to uncover a clay tablet inscribed with symbols that bore no resemblance to any known writing system of the period.', $lyceon_json$[{"key":"A","text":"artifacts, was startled"},{"key":"B","text":"artifacts; was startled"},{"key":"C","text":"artifacts was startled"},{"key":"D","text":"artifacts. Was startled"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct choice is "artifacts, was startled" because the sentence contains a nonrestrictive relative clause, "whose excavation of a Bronze Age settlement near the Danube had already yielded over three hundred artifacts," which modifies "The archaeologist." This clause, opened by a comma before "whose," must be closed by a matching comma after "artifacts" so the main verb "was startled" can follow. The choice "artifacts; was startled" incorrectly uses a semicolon, which cannot close a parenthetical clause embedded within a sentence. The choice "artifacts was startled" omits the required closing comma, creating a boundary error that makes the sentence structure unclear. The choice "artifacts. Was startled" places a period after the relative clause, producing the fragment "Was startled to uncover a clay tablet" which lacks a subject.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZXHM16', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'Ecologist Suzanne Simard''s research on Douglas fir forests revealed that trees share carbon, water, and nutrients through underground mycorrhizal networks connecting their root systems. Her team''s isotope-tracing experiments showed that older, larger trees -- termed "mother trees" -- transfer surplus carbon to smaller, shaded seedlings, particularly those that are genetically related. However, Simard has cautioned against interpreting these transfers as purely altruistic. The chemical exchanges may also benefit the fungal intermediaries, which extract carbon from both partners, and the mother trees themselves may gain enhanced root-fungal connections that improve their own nutrient uptake. The network, Simard argues, is better understood as a complex mutualism in which each participant''s interests overlap without perfectly aligning.', $lyceon_json$[{"key":"A","text":"Simard's research shows that underground mycorrhizal networks facilitate resource sharing among trees, but the exchanges reflect a complex mutualism rather than simple altruism."},{"key":"B","text":"Simard discovered that Douglas fir forests contain mycorrhizal networks, a finding that overturned the previous scientific consensus that trees compete rather than cooperate."},{"key":"C","text":"Simard's isotope-tracing experiments proved that older trees sacrifice their own nutrient intake to ensure the survival of genetically related seedlings in shaded areas of the forest."},{"key":"D","text":"Simard argues that fungal intermediaries are the primary beneficiaries of mycorrhizal networks, extracting more carbon than they deliver to either the mother trees or the seedlings."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes Simard''s discovery of mycorrhizal resource sharing and then pivots to her caution that the exchanges are not purely altruistic but instead constitute a complex mutualism. The choice identifying both the resource sharing and the mutualism framing captures this two-part main idea. The choice about overturning a consensus on competition introduces a claim not made in the passage. The choice about older trees sacrificing their nutrient intake contradicts the passage, which states mother trees may gain enhanced nutrient uptake through the network. The choice casting fungi as the primary beneficiaries distorts the passage''s point; Simard describes overlapping interests among all participants, not fungal dominance.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
